"use client";

import { useState } from "react";

import { Button } from "@/components/ui/button";
import {
	Dialog,
	DialogClose,
	DialogContent,
	DialogDescription,
	DialogFooter,
	DialogHeader,
	DialogTitle,
	DialogTrigger,
} from "@/components/ui/dialog";
import { ArrowRightIcon } from "lucide-react";

import { cn } from "@/lib/utils";

export default function Component() {
	const [step, setStep] = useState(1);

	const stepContent = [
		{
			title: "Welcome to Origin UI",
			description:
				"Discover a powerful collection of components designed to enhance your development workflow.",
		},
		{
			title: "Customizable Components",
			description:
				"Each component is fully customizable and built with modern web standards in mind.",
		},
		{
			title: "Ready to Start?",
			description:
				"Begin building amazing interfaces with our comprehensive component library.",
		},
		{
			title: "Get Support",
			description:
				"Access our extensive documentation and community resources to make the most of Origin UI.",
		},
	];

	const totalSteps = stepContent.length;

	const handleContinue = () => {
		if (step < totalSteps) {
			setStep(step + 1);
		}
	};

	return (
		<Dialog
			onOpenChange={(open) => {
				if (open) setStep(1);
			}}
		>
			<DialogTrigger asChild>
				<Button variant="outline">Onboarding</Button>
			</DialogTrigger>
			<DialogContent className="gap-0 p-0 [&>button:last-child]:text-white">
				<div className="p-2">
					<img
						className="w-full rounded-md"
						src="/dialog-content.png"
						width={382}
						height={216}
						alt="dialog"
					/>
				</div>
				<div className="space-y-6 px-6 pt-3 pb-6">
					<DialogHeader>
						<DialogTitle>{stepContent[step - 1].title}</DialogTitle>
						<DialogDescription>
							{stepContent[step - 1].description}
						</DialogDescription>
					</DialogHeader>
					<div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center">
						<div className="flex justify-center space-x-1.5 max-sm:order-1">
							{[...Array(totalSteps)].map((_, index) => (
								<div
									key={index}
									className={cn(
										"bg-primary size-1.5 rounded-full",
										index + 1 === step ? "bg-primary" : "opacity-20"
									)}
								/>
							))}
						</div>
						<DialogFooter>
							<DialogClose asChild>
								<Button type="button" variant="ghost">
									Skip
								</Button>
							</DialogClose>
							{step < totalSteps ? (
								<Button
									className="group"
									type="button"
									onClick={handleContinue}
								>
									Next
									<ArrowRightIcon
										className="-me-1 opacity-60 transition-transform group-hover:translate-x-0.5"
										size={16}
										aria-hidden="true"
									/>
								</Button>
							) : (
								<DialogClose asChild>
									<Button type="button">Okay</Button>
								</DialogClose>
							)}
						</DialogFooter>
					</div>
				</div>
			</DialogContent>
		</Dialog>
	);
}

import * as React from "react";

import { cn } from "@/lib/utils";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };
